#[test]
fn years365() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x * 365.0 * 24.0 * 3600.0;
        assert_close(Duration::from_years365(v).as_base(), base, F64_TOL);
        let x: f64 = base;
        let back = x / (365.0 * 24.0 * 3600.0);
        assert_close(Duration::from_base(base).as_years365(), back, F64_TOL);
        assert_close(Duration::from_years365(v).as_years365(), v, ROUND_TRIP_TOL);
        // f32 storage.
        assert_close(
            Duration::from_years365(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            Duration::from_base(base as f32).as_years365() as f64,
            back,
            F32_TOL,
        );
    }
}

