#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [Duration; 13] = [
        Duration::const_new(1234.5, DurationUnit::Year365),
        Duration::const_new(1234.5, DurationUnit::Month30),
        Duration::const_new(1234.5, DurationUnit::Week),
        Duration::const_new(1234.5, DurationUnit::Day),
        Duration::const_new(1234.5, DurationUnit::Hour),
        Duration::const_new(1234.5, DurationUnit::Minute),
        Duration::const_new(1234.5, DurationUnit::Second),
        Duration::const_new(1234.5, DurationUnit::Picosecond),
        Duration::const_new(1234.5, DurationUnit::Nanosecond),
        Duration::const_new(1234.5, DurationUnit::Microsecond),
        Duration::const_new(1234.5, DurationUnit::Millisecond),
        Duration::const_new(1234.5, DurationUnit::JulianYear),
        Duration::const_new(1234.5, DurationUnit::Sol),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(DurationUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            Duration::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in DurationUnit::ALL {
            assert_eq!(
                Duration::const_new(v, unit).as_base().to_bits(),
                Duration::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = Duration::from_base(v);
        let auto = q.auto_unit();
        assert_close(Duration::new(auto.value, auto.unit).as_base(), v, F64_TOL);
        for &unit in DurationUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        Duration::from_base(0.0).auto_unit().unit,
        DurationUnit::Second
    );
}

#[test]
