    assert_eq!("yr".parse::<DurationUnit>(), Ok(DurationUnit::Year365));
    assert_eq!(
        format!("2.5 {}", "yr").parse::<Duration>(),
        Ok(Duration::new(2.5, DurationUnit::Year365))
    );
